import java.util.Scanner;

public class TemperatureAdvice {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter temperature: ");
        int temperature = scanner.nextInt();

        if (temperature < 0) {
